        {
          "type": "null"
        }
      ]
    }
  ]
}

{
  "title": "agent.completions.message.UserMessageExpression",
  "description": "Expression variant of [`UserMessage`] for dynamic content.",
  "type": "object",
  "properties": {
    "content": {
      "description": "The message content expression.",
